.data-labels {
  font-size: 12px;
  text-anchor: middle;
  font-family: helvetica, arial, sans-serif;
  pointer-events: none;
}
.radarChart .axis path,
.radarChart .axis line {
  fill: none;
  stroke: grey;
  stroke-width: 1px;
}
.radarChart .axis text {
  font-family: sans-serif;
}
.radarChart .axisLongLabelLink,
.radarChart .axisShortLabelLink {
  stroke-opacity: 0.5;
  fill: none;
  stroke: #e1e1e1;
  stroke-width: 1px;
}
.radarChart .segments path,
.radarChart .segments line {
  fill: none;
  stroke: grey;
  stroke-opacity: 0.75;
  stroke-width: 0.3px;
}
.radarChart .zeroSegment path,
.radarChart .zeroSegment line {
  fill: none;
  stroke: grey;
  stroke-opacity: 0.75;
  stroke-width: 2px;
}
.radarChart .zeroSegment text {
  fill: none;
  stroke: grey;
  stroke-opacity: 0.75;
  stroke-width: 1px;
  font-size: 10px;
}
.radarChart .chartDot {
  stroke-width: 0px;
  transition: stroke-width 100ms;
}
.radarChart .chartDot:focus {
  outline: none;
}
.radarChart .chartDot:focus-visible {
  outline: auto 1px;
  border-radius: 5px;
  outline-color: -webkit-focus-ring-color;
}
.radarChart .chartDot:hover {
  stroke-width: 5px;
}
